'use client';

import type { Variants } from 'motion/react';
import type { HTMLAttributes } from 'react';
import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
} from 'react';
import { motion, useAnimation, useReducedMotion } from 'motion/react';

import { cn } from '@/lib/utils';

export interface HugeiconsSprayCanIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}
interface HugeiconsSprayCanIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

const ICON_VARIANTS: Variants = {
  normal: {
    x: 0,
    y: 0,
    rotate: 0,
    scale: 1,
    scaleX: 1,
    scaleY: 1,
    opacity: 1,
    transition: { duration: 0.18, ease: 'easeOut' },
  },
  animate: { transition: { duration: 0.9, ease: 'easeInOut' } },
};

const DETAIL_0_VARIANTS: Variants = {
  normal: { x: 0, opacity: 1, transition: { duration: 0.18, ease: 'easeOut' } },
  animate: {
    x: [0, 0.7, 0],
    opacity: [1, 0.25, 1],
    transition: { duration: 0.75, delay: 0, ease: 'easeInOut' },
  },
};

const HugeiconsSprayCanIcon = forwardRef<
  HugeiconsSprayCanIconHandle,
  HugeiconsSprayCanIconProps
>(
  (
    {
      onMouseEnter,
      onMouseLeave,
      onFocus,
      onBlur,
      className,
      size = 28,
      ...props
    },
    ref
  ) => {
    const controls = useAnimation();
    const reducedMotion = useReducedMotion();
    const sequence = useRef(0);
    const startAnimation = useCallback(() => {
      const current = ++sequence.current;
      controls.stop();
      controls.set('normal');
      if (reducedMotion) return;
      void controls.start('animate').then(() => {
        if (sequence.current === current) controls.set('normal');
      });
    }, [controls, reducedMotion]);
    const stopAnimation = useCallback(() => {
      sequence.current += 1;
      void controls.start('normal');
    }, [controls]);
    useImperativeHandle(ref, () => ({ startAnimation, stopAnimation }), [
      startAnimation,
      stopAnimation,
    ]);
    useEffect(() => {
      if (reducedMotion) {
        sequence.current += 1;
        controls.set('normal');
      }
      return () => {
        sequence.current += 1;
        controls.stop();
      };
    }, [controls, reducedMotion]);
    return (
      <div
        {...props}
        className={cn(className)}
        onMouseEnter={(event) => {
          if (!ref) startAnimation();
          onMouseEnter?.(event);
        }}
        onMouseLeave={(event) => {
          if (!ref) stopAnimation();
          onMouseLeave?.(event);
        }}
        onFocus={(event) => {
          if (!ref) startAnimation();
          onFocus?.(event);
        }}
        onBlur={(event) => {
          if (!ref) stopAnimation();
          onBlur?.(event);
        }}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
          aria-hidden="true"
          focusable="false"
        >
          <motion.g
            initial="normal"
            animate={controls}
            variants={ICON_VARIANTS}
            style={{ transformOrigin: '12px 12px' }}
          >
            <path
              d="M10 8V6C10 5.53501 10 5.30252 9.94889 5.11177C9.81019 4.59413 9.40587 4.18981 8.88823 4.05111C8.69748 4 8.46499 4 8 4C7.53501 4 7.30252 4 7.11177 4.05111C6.59413 4.18981 6.18981 4.59413 6.05111 5.11177C6 5.30252 6 5.53501 6 6V8H10Z"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
            <path
              d="M10 8H6L5.3436 8.9846C4.67671 9.98494 4.34326 10.4851 4.17163 11.052C4 11.6188 4 12.22 4 13.4222V18C4 19.8856 4 20.8284 4.58579 21.4142C5.17157 22 6.11438 22 8 22C9.88562 22 10.8284 22 11.4142 21.4142C12 20.8284 12 19.8856 12 18V13.4222C12 12.22 12 11.6188 11.8284 11.052C11.6567 10.4851 11.3233 9.98494 10.6564 8.9846L10 8Z"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
            <path
              d="M11.5 12H11C9.58579 12 8.87868 12 8.43934 12.4393C8 12.8787 8 13.5858 8 15C8 16.4142 8 17.1213 8.43934 17.5607C8.87868 18 9.58579 18 11 18H11.5"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
            <motion.path
              d="M13.875 5.99994H13.75M19.875 5.99994H19.75M16.875 7.99994H16.75M16.875 3.99994H16.75M19.875 2.25H19.75M19.875 9.75H19.75M14 5.99994C14 6.13801 13.8881 6.24994 13.75 6.24994C13.6119 6.24994 13.5 6.13801 13.5 5.99994C13.5 5.86187 13.6119 5.74994 13.75 5.74994C13.8881 5.74994 14 5.86187 14 5.99994ZM20 5.99994C20 6.13801 19.8881 6.24994 19.75 6.24994C19.6119 6.24994 19.5 6.13801 19.5 5.99994C19.5 5.86187 19.6119 5.74994 19.75 5.74994C19.8881 5.74994 20 5.86187 20 5.99994ZM17 7.99994C17 8.13801 16.8881 8.24994 16.75 8.24994C16.6119 8.24994 16.5 8.13801 16.5 7.99994C16.5 7.86187 16.6119 7.74994 16.75 7.74994C16.8881 7.74994 17 7.86187 17 7.99994ZM17 3.99994C17 4.13801 16.8881 4.24994 16.75 4.24994C16.6119 4.24994 16.5 4.13801 16.5 3.99994C16.5 3.86187 16.6119 3.74994 16.75 3.74994C16.8881 3.74994 17 3.86187 17 3.99994ZM20 2.25C20 2.38807 19.8881 2.5 19.75 2.5C19.6119 2.5 19.5 2.38807 19.5 2.25C19.5 2.11193 19.6119 2 19.75 2C19.8881 2 20 2.11193 20 2.25ZM20 9.75C20 9.88807 19.8881 10 19.75 10C19.6119 10 19.5 9.88807 19.5 9.75C19.5 9.61193 19.6119 9.5 19.75 9.5C19.8881 9.5 20 9.61193 20 9.75Z"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
              variants={DETAIL_0_VARIANTS}
              style={{ transformBox: 'fill-box', transformOrigin: 'center' }}
            />
          </motion.g>
        </svg>
      </div>
    );
  }
);
HugeiconsSprayCanIcon.displayName = 'HugeiconsSprayCanIcon';
export { HugeiconsSprayCanIcon };
